import {createApi} from './focus-api.mjs';
import {sandboxScenario} from './sandbox-scenarios.mjs';

const api=createApi(),status=document.querySelector('#checkout-status'),result=document.querySelector('#result'),form=document.querySelector('#buyer-form'),gate=document.querySelector('#operator-gate'),purchaseFields=document.querySelector('#purchase-fields'),retry=document.querySelector('#retry-panel'),scenarioSelect=document.querySelector('#sandbox-scenario'),scenarioDetail=document.querySelector('#scenario-detail');
let requestId=sessionStorage.getItem('paytrace-demo-store-request'),draft=null,ready=false;
const requestedScenario=new URLSearchParams(location.search).get('scenario');if(sandboxScenario(requestedScenario))scenarioSelect.value=requestedScenario;
if(new URLSearchParams(location.search).get('from')==='course')document.querySelector('.scenario-choice').hidden=true;
function updateScenario(){scenarioDetail.textContent=sandboxScenario(scenarioSelect.value)?.detail||'';}
scenarioSelect.addEventListener('change',updateScenario);updateScenario();
function message(text,error=false){status.textContent=text;status.classList.toggle('error',error);}
function lockPurchase(locked){form.querySelectorAll('input').forEach(input=>input.disabled=locked);}
function success(row){sessionStorage.removeItem('paytrace-demo-store-request');sessionStorage.setItem('paytrace-course-purchase',JSON.stringify({requestId:row.requestId,orderId:row.orderId,email:row.email}));retry.hidden=true;purchaseFields.hidden=true;scenarioSelect.disabled=true;document.querySelector('#paypal-buttons').replaceChildren();message('Sandbox capture verified. Return to the workshop and try opening your lesson.');result.replaceChildren();const card=document.createElement('div');card.className='result-card';const title=document.createElement('strong');title.textContent='Payment confirmed';const p=document.createElement('p');p.textContent='Your PayPal sandbox purchase is complete. Use this order number and your checkout email to sign in at the workshop.';const reference=document.createElement('p');reference.className='order-reference';reference.textContent='Order number: '+row.orderId;const link=document.createElement('a');link.href='course.html?from=checkout#learner-sign-in';link.textContent='Return to the workshop →';const merchant=document.createElement('a');merchant.href='focus.html?caseId='+encodeURIComponent(row.caseId);merchant.className='result-again';merchant.textContent='Merchant case';card.append(title,p,reference,link,merchant);result.append(card);}
async function complete(){if(!draft?.requestId||!draft.orderId)return;message('Capturing and rereading the PayPal sandbox payment…');retry.hidden=true;try{const row=await api('demo-store/complete',{requestId:draft.requestId,orderId:draft.orderId},{requestTimeoutMs:60000});draft=row;success(row);}catch(error){message(error.message+' The checkout request is saved; retry will use the same order.',true);retry.hidden=false;}}
document.querySelector('#retry-complete').onclick=complete;
async function loadSdk(){if(!window.COURSELATCH_RUNTIME?.paypal||!window.COURSELATCH_RUNTIME?.paypalClientId)throw Error('PayPal sandbox checkout is unavailable.');const script=document.createElement('script');script.src='https://www.paypal.com/sdk/js?client-id='+encodeURIComponent(window.COURSELATCH_RUNTIME.paypalClientId)+'&currency=USD&intent=capture';await new Promise((resolve,reject)=>{script.onload=resolve;script.onerror=()=>reject(Error('PayPal sandbox buttons could not load.'));document.head.append(script);});if(!window.paypal?.Buttons)throw Error('PayPal sandbox buttons are unavailable.');}
async function mountButtons(){if(ready)return;ready=true;purchaseFields.hidden=false;document.querySelector('#paypal-buttons').hidden=false;try{await loadSdk();await window.paypal.Buttons({
  createOrder:async()=>{if(!form.reportValidity())throw Error('Enter the buyer details before checkout.');requestId||=crypto.randomUUID();sessionStorage.setItem('paytrace-demo-store-request',requestId);message('Creating a PayPal sandbox order…');const row=await api('demo-store/start',{requestId,customerName:form.elements.customerName.value,email:form.elements.email.value,scenario:scenarioSelect.value},{requestTimeoutMs:60000});draft=row;lockPurchase(true);scenarioSelect.disabled=true;message('PayPal sandbox order ready. Approve it with a sandbox buyer account.');return row.orderId;},
  onApprove:async data=>{if(draft&&data.orderID!==draft.orderId){message('PayPal returned a different order. No case was created.',true);return;}await complete();},
  onCancel:()=>message('Checkout canceled. No recovery case was created. You can resume this sandbox order.'),
  onError:()=>message('Sandbox checkout could not complete. If payment was approved, use the safe retry below.',true)
 }).render('#paypal-buttons');message(draft?.orderId?'Existing sandbox order ready. Approve it with a sandbox buyer account.':'Enter test buyer details, then continue with PayPal sandbox.');}catch(error){document.querySelector('#paypal-buttons').hidden=true;message(error.message+' Refresh this page to try again.',true);ready=false;}}
async function init(){try{const state=await api('state');if(window.COURSELATCH_RUNTIME?.authRequired){message('This merchant-operated demo store is only available in sandbox demo mode.',true);return;}if(!window.COURSELATCH_RUNTIME?.paypal){message('PayPal sandbox credentials are not configured on this app.',true);return;}if(requestId){const previous=await api('demo-store/status?requestId='+encodeURIComponent(requestId)).catch(()=>null);if(previous?.status==='case-created'){success(previous);return;}if(previous?.orderId){draft=previous;scenarioSelect.value=previous.scenario||'missing-access';updateScenario();scenarioSelect.disabled=true;form.elements.customerName.value=previous.customerName;form.elements.email.value=previous.email;lockPurchase(true);retry.hidden=false;}}
 if(!state.operator){gate.hidden=false;message('Unlock merchant controls to begin a sandbox store checkout.');return;}await mountButtons();}catch(error){message(error.message,true);}}
document.querySelector('#operator-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;message('Unlocking merchant controls…');try{await api('operator',{key:new FormData(event.target).get('key')});event.target.reset();gate.hidden=true;message('Merchant controls unlocked.');await mountButtons();}catch(error){message(error.message,true);button.disabled=false;}};
init();
